@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private bool isProcessing = false;
    private bool isSubmitted = false;
    private int submittedApplicationId;
    private List<string> errors = new();

    // Step 1: Personal Info
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int step) => step < currentStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            currentStep = step;
            errors.Clear();
        }
    }

    private void GoToStep(int step)
    {
        currentStep = step;
        errors.Clear();
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
        {
            currentStep--;
            errors.Clear();
        }
    }

    private async Task NextStep()
    {
        errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (currentStep == 0)
        {
            isProcessing = true;
            try
            {
                var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
                if (!isValidEmail)
                {
                    errors.Add("The email address is not valid. Please enter a valid email.");
                    return;
                }
            }
            finally
            {
                isProcessing = false;
            }
        }

        if (currentStep < StepNames.Length - 1)
            currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        return currentStep switch
        {
            0 => ValidatePersonalInfo(),
            1 => ValidateWorkHistory(),
            2 => ValidateReferences(),
            3 => ValidateCoverLetter(),
            _ => true
        };
    }

    private bool ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(fullName))
            errors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(email))
            errors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(phone))
            errors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(address))
            errors.Add("Address is required.");
        return errors.Count == 0;
    }

    private bool ValidateWorkHistory()
    {
        for (int i = 0; i < workEntries.Count; i++)
        {
            var entry = workEntries[i];
            if (string.IsNullOrWhiteSpace(entry.Company))
                errors.Add($"Position {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                errors.Add($"Position {i + 1}: Job title is required.");
            if (entry.StartDate == default)
                errors.Add($"Position {i + 1}: Start date is required.");
            if (string.IsNullOrWhiteSpace(entry.Description))
                errors.Add($"Position {i + 1}: Description is required.");
        }
        return errors.Count == 0;
    }

    private bool ValidateReferences()
    {
        for (int i = 0; i < references.Count; i++)
        {
            var r = references[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                errors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                errors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                errors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                errors.Add($"Reference {i + 1}: Phone is required.");
        }
        return errors.Count == 0;
    }

    private bool ValidateCoverLetter()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
            errors.Add("Cover letter is required.");
        return errors.Count == 0;
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        isProcessing = true;
        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
