        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (errors.Count > 0)
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    @if (!isSubmitted)
    {
        @switch (currentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReview()
                break;
        }
    }
    else
    {
        <div class="submission-confirmation">
            <h2>&#10003; Application Submitted Successfully!</h2>
            <p>Your application ID is: <strong>@submittedApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
