+                        <span>@(stepIndex + 1)</span>
+                    }
+                </div>
+                <div class="step-label">@StepNames[stepIndex]</div>
+            </div>
+            @if (stepIndex < StepNames.Length - 1)
+            {
+                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
+            }
+        }
+    </div>
+
+    @* Validation Errors *@
+    @if (errors.Count > 0)
+    {
+        <div class="validation-errors">
+            <ul>
+                @foreach (var error in errors)
+                {
+                    <li>@error</li>
+                }
+            </ul>
+        </div>
+    }
+
+    @* Step Content *@
+    @if (!isSubmitted)
+    {
+        @switch (currentStep)
+        {
+            case 0:
+                @RenderPersonalInfo()
+                break;
+            case 1:
+                @RenderWorkHistory()
+                break;
+            case 2:
+                @RenderReferences()
+                break;
+            case 3:
+                @RenderCoverLetter()
+                break;
+            case 4:
+                @RenderReview()
+                break;
+        }
+    }
+    else
+    {
+        <div class="submission-confirmation">
+            <h2>&#10003; Application Submitted Successfully!</h2>
+            <p>Your application ID is: <strong>@submittedApplicationId</strong></p>
+            <p>Thank you for applying. We will review your application and get back to you.</p>
+        </div>
+    }
+</div>
+
+@* Step 1: Personal Info *@
+@{
+    RenderFragment RenderPersonalInfo() => __builder2 =>
+    {
+        <div class="form-step">
+            <h2>Personal Information</h2>
+            <div class="form-group">
+                <label for="fullName">Full Name *</label>
+                <input id="fullName" type="text" @bind="fullName" placeholder="Enter your full name" />
+            </div>
+            <div class="form-group">
+                <label for="email">Email *</label>
+                <input id="email" type="email" @bind="email" placeholder="Enter your email" />
+            </div>
+            <div class="form-group">
+                <label for="phone">Phone *</label>
+                <input id="phone" type="tel" @bind="phone" placeholder="Enter your phone number" />
+            </div>
+            <div class="form-group">
+                <label for="address">Address *</label>
+                <textarea id="address" @bind="address" placeholder="Enter your address"></textarea>
+            </div>
+            <div class="form-navigation">
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@isProcessing">
+                    @if (isProcessing)
+                    {
+                        <span>Validating...</span>
+                    }
+                    else
+                    {
+                        <span>Next</span>
+                    }
+                </button>
+            </div>
+        </div>
+    };
+}
+
+@* Step 2: Work History *@
+@{
+    RenderFragment RenderWorkHistory() => __builder2 =>
+    {
+        <div class="form-step">
+            <h2>Work History</h2>
+            @for (int i = 0; i < workEntries.Count; i++)
+            {
+                var index = i;
+                <div class="work-entry-card">
+                    <div class="work-entry-header">
+                        <h3>Position @(index + 1)</h3>
+                        @if (workEntries.Count > 1)
+                        {
+                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                        }
+                    </div>
+                    <div class="form-group">
+                        <label>Company Name *</label>
+                        <input type="text" @bind="workEntries[index].Company" placeholder="Company name" />
+                    </div>
+                    <div class="form-group">
+                        <label>Job Title *</label>
+                        <input type="text" @bind="workEntries[index].Title" placeholder="Job title" />
+                    </div>
+                    <div class="form-row">
+                        <div class="form-group">
+                            <label>Start Date *</label>
+                            <input type="date" @bind="workEntries[index].StartDate" />
+                        </div>
+                        <div class="form-group">
+                            <label>End Date</label>
+                            <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
+                        </div>
+                    </div>
+                    <div class="form-group form-check">
+                        <input type="checkbox" id="@($"current-{index}")" @bind="workEntries[index].IsCurrent" />
+                        <label for="@($"current-{index}")">I currently work here</label>
+                    </div>
+                    <div class="form-group">
+                        <label>Description *</label>
+                        <textarea @bind="workEntries[index].Description" placeholder="Describe your responsibilities and achievements"></textarea>
+                    </div>
+                </div>
+            }
+            <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
+            <div class="form-navigation">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>
+    };
+}
+
+@* Step 3: References *@
+@{
+    RenderFragment RenderReferences() => __builder2 =>
+    {
+        <div class="form-step">
+            <h2>References</h2>
+            @for (int i = 0; i < references.Count; i++)
+            {
+                var index = i;
+                <div class="reference-card">
+                    <div class="work-entry-header">
+                        <h3>Reference @(index + 1)</h3>
+                        @if (references.Count > 2)
+                        {
+                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                        }
+                    </div>
+                    <div class="form-group">
+                        <label>Name *</label>
+                        <input type="text" @bind="references[index].Name" placeholder="Reference name" />
+                    </div>
+                    <div class="form-group">
+                        <label>Relationship *</label>
+                        <input type="text" @bind="references[index].Relationship" placeholder="e.g. Former Manager" />
+                    </div>
+                    <div class="form-group">
+                        <label>Email *</label>
+                        <input type="email" @bind="references[index].Email" placeholder="Reference email" />
+                    </div>
+                    <div class="form-group">
+                        <label>Phone *</label>
+                        <input type="tel" @bind="references[index].Phone" placeholder="Reference phone" />
+                    </div>
+                </div>
+            }
+            @if (references.Count < 3)
+            {
+                <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
+            }
+            <div class="form-navigation">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>
+    };
+}
+
+@* Step 4: Cover Letter *@
+@{
+    RenderFragment RenderCoverLetter() => __builder2 =>
+    {
+        <div class="form-step">
+            <h2>Cover Letter</h2>
+            <div class="form-group">
+                <label for="coverLetter">Write your cover letter *</label>
+                <textarea id="coverLetter" class="cover-letter-textarea" @bind="coverLetter" @bind:event="oninput"
+                    placeholder="Tell us why you're a great fit for this role..." maxlength="2000"></textarea>
+                <div class="character-count @(coverLetter.Length > 1800 ? "warning" : "")">
+                    @coverLetter.Length / 2000 characters
+                </div>
+            </div>
+            <div class="form-navigation">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep">Next</button>
+            </div>
+        </div>
+    };
+}
+
+@* Step 5: Review & Submit *@
+@{
+    RenderFragment RenderReview() => __builder2 =>
+    {
+        <div class="form-step">
+            <h2>Review & Submit</h2>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Personal Information</h3>
+                    <button class="btn-link" @onclick="() => GoToStep(0)">Edit</button>
+                </div>
+                <dl>
+                    <dt>Full Name</dt><dd>@fullName</dd>
+                    <dt>Email</dt><dd>@email</dd>
+                    <dt>Phone</dt><dd>@phone</dd>
+                    <dt>Address</dt><dd>@address</dd>
+                </dl>
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Work History</h3>
+                    <button class="btn-link" @onclick="() => GoToStep(1)">Edit</button>
+                </div>
+                @foreach (var entry in workEntries)
+                {
+                    <div class="review-work-entry">
+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
+                        <br />
+                        <span class="text-muted">
+                            @entry.StartDate.ToString("MMM yyyy") &mdash;
+                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
+                        </span>
+                        <p>@entry.Description</p>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>References</h3>
+                    <button class="btn-link" @onclick="() => GoToStep(2)">Edit</button>
+                </div>
+                @foreach (var reference in references)
+                {
+                    <div class="review-reference">
+                        <strong>@reference.Name</strong> (@reference.Relationship)
+                        <br />
+                        <span class="text-muted">@reference.Email | @reference.Phone</span>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Cover Letter</h3>
+                    <button class="btn-link" @onclick="() => GoToStep(3)">Edit</button>
+                </div>
+                <p class="cover-letter-preview">@coverLetter</p>
+            </div>
+
+            <div class="form-navigation">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@isProcessing">
+                    @if (isProcessing)
+                    {
+                        <span>Submitting...</span>
+                    }
+                    else
+                    {
+                        <span>Submit Application</span>
+                    }
+                </button>
+            </div>
+        </div>
+    };
+}
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int currentStep = 0;
+    private bool isProcessing = false;
+    private bool isSubmitted = false;
+    private int submittedApplicationId;
+    private List<string> errors = new();
+
+    // Step 1: Personal Info
+    private string fullName = string.Empty;
+    private string email = string.Empty;
+    private string phone = string.Empty;
+    private string address = string.Empty;
+
+    // Step 2: Work History
+    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string coverLetter = string.Empty;
+
+    private string GetStepClass(int step)
+    {
+        if (step == currentStep) return "active";
+        if (IsStepCompleted(step)) return "completed";
+        return "future";
+    }
+
+    private bool IsStepCompleted(int step) => step < currentStep;
+
+    private void NavigateToStep(int step)
+    {
+        if (IsStepCompleted(step))
+        {
+            currentStep = step;
+            errors.Clear();
+        }
+    }
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+        errors.Clear();
+    }
+
+    private void PreviousStep()
+    {
+        if (currentStep > 0)
+        {
+            currentStep--;
+            errors.Clear();
+        }
+    }
+
+    private async Task NextStep()
+    {
+        errors.Clear();
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (currentStep == 0)
+        {
+            isProcessing = true;
+            try
+            {
+                var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
+                if (!isValidEmail)
+                {
+                    errors.Add("The email address is not valid. Please enter a valid email.");
+                    return;
+                }
+            }
+            finally
+            {
+                isProcessing = false;
+            }
+        }
+
+        if (currentStep < StepNames.Length - 1)
+            currentStep++;
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        return currentStep switch
+        {
+            0 => ValidatePersonalInfo(),
+            1 => ValidateWorkHistory(),
+            2 => ValidateReferences(),
+            3 => ValidateCoverLetter(),
+            _ => true
+        };
+    }
+
+    private bool ValidatePersonalInfo()
+    {
+        if (string.IsNullOrWhiteSpace(fullName))
+            errors.Add("Full name is required.");
+        if (string.IsNullOrWhiteSpace(email))
+            errors.Add("Email is required.");
+        if (string.IsNullOrWhiteSpace(phone))
+            errors.Add("Phone is required.");
+        if (string.IsNullOrWhiteSpace(address))
+            errors.Add("Address is required.");
+        return errors.Count == 0;
+    }
+
+    private bool ValidateWorkHistory()
+    {
+        for (int i = 0; i < workEntries.Count; i++)
+        {
+            var entry = workEntries[i];
+            if (string.IsNullOrWhiteSpace(entry.Company))
+                errors.Add($"Position {i + 1}: Company name is required.");
+            if (string.IsNullOrWhiteSpace(entry.Title))
+                errors.Add($"Position {i + 1}: Job title is required.");
+            if (entry.StartDate == default)
+                errors.Add($"Position {i + 1}: Start date is required.");
+            if (string.IsNullOrWhiteSpace(entry.Description))
+                errors.Add($"Position {i + 1}: Description is required.");
+        }
+        return errors.Count == 0;
+    }
+
+    private bool ValidateReferences()
+    {
+        for (int i = 0; i < references.Count; i++)
+        {
+            var r = references[i];
+            if (string.IsNullOrWhiteSpace(r.Name))
+                errors.Add($"Reference {i + 1}: Name is required.");
+            if (string.IsNullOrWhiteSpace(r.Relationship))
+                errors.Add($"Reference {i + 1}: Relationship is required.");
+            if (string.IsNullOrWhiteSpace(r.Email))
+                errors.Add($"Reference {i + 1}: Email is required.");
+            if (string.IsNullOrWhiteSpace(r.Phone))
+                errors.Add($"Reference {i + 1}: Phone is required.");
+        }
+        return errors.Count == 0;
+    }
+
+    private bool ValidateCoverLetter()
+    {
+        if (string.IsNullOrWhiteSpace(coverLetter))
+            errors.Add("Cover letter is required.");
+        return errors.Count == 0;
+    }
+
+    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (workEntries.Count > 1)
+            workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (references.Count < 3)
+            references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (references.Count > 2)
+            references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        isProcessing = true;
+        try
+        {
+            var personal = new PersonalInfo(fullName, email, phone, address);
+            var work = new WorkHistory(workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, work, refs, coverLetter);
+
+            submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

arguments.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    transition: background 0.3s ease;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

/* Form Elements */
.form-step {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.form-step h2 {
    margin-bottom: 1.5rem;
    color: #212529;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.form-check input[type="checkbox"] {
    width: auto;
}

.form-check label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-success {
    background: #198754;
    color: #fff;
}

.btn-success:hover:not(:disabled) {
    background: #157347;
}

.btn-outline {
    background: #fff;
    color: #6c757d;
    border: 1px solid #6c757d;
}

.btn-outline:hover {
    background: #f8f9fa;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
    margin-bottom: 1rem;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-link:hover {
    color: #0b5ed7;
}

/* Navigation */
.form-navigation {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #dee2e6;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.character-count.warning {
    color: #dc3545;
    font-weight: 600;
}

/* Validation Errors */
.validation-errors {
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.25rem;
    color: #842029;
}

/* Review Section */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #495057;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.text-muted {
    color: #6c757d;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #d1e7dd;
